previewCss:
.darma-loader-darma-b7-snake-track { --accent: var(--loader-color, #22d3ee); --accent-2: var(--loader-secondary-color, #f472b6); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b7-snake-track span { position: absolute; top: 0; left: 0; width: calc(var(--loader-size, 80px) * .18); height: calc(var(--loader-size, 80px) * .18); border-radius: 28%; background: var(--accent); animation: darma-loader-darma-b7-snake-track-lap calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b7-snake-track span:nth-child(1) { background: var(--accent-2); animation-delay: 0s; }
.darma-loader-darma-b7-snake-track span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -.18); }
.darma-loader-darma-b7-snake-track span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * -.36); }
.darma-loader-darma-b7-snake-track span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * -.54); }
@keyframes darma-loader-darma-b7-snake-track-lap { 0% { transform: translate(0, 0); } 25% { transform: translate(calc(var(--loader-size, 80px) * .82), 0); } 50% { transform: translate(calc(var(--loader-size, 80px) * .82), calc(var(--loader-size, 80px) * .82)); } 75% { transform: translate(0, calc(var(--loader-size, 80px) * .82)); } 100% { transform: translate(0, 0); } }

